const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v===null?'—':'$'+Number(v||0).toFixed(2);
export function briefFields(f,workflows,run){
 const b=['needs_brief','needs_changes'].includes(run?.status)?run.brief||{}:f.taskBrief||{};
 return `<details class="wt-brief" open><summary>Task brief · complete before starting</summary><div class="wt-grid">${[
 ['outcome','Outcome','The usable result you need'],['audience','Audience','Who will use or read this?'],['files','Files and sources','Add files on Brief & training; list names here, or say none needed'],['constraints','Constraints','Tone, deadline, limits; or none'],['finished','Finished means','Checks the reviewer must pass'],['preferences','Writing preferences (optional)','Style, wording, examples to follow'],['checklist','Checklist (optional)','Repeatable checks for this kind of work']
 ].map(([key,label,hint])=>`<label>${label}<textarea rows="2" data-brief="${key}" maxlength="2000" placeholder="${hint}">${esc(b[key])}</textarea></label>`).join('')}<label>Budget ceiling · estimated USD<input data-brief="budget" type="number" min="0.05" max="${f.budget.perRun}" step="0.05" value="${b.budget||f.budget.perRun}"></label></div><p>Critical gaps pause the run. Estimates can overshoot by an in-flight model call; Claude Code subscription usage may not report a dollar cost.</p><label>Accepted example<select data-workflow><option value="">No example</option>${workflows.filter(w=>w.floorId===f.id).map(w=>`<option value="${esc(w.id)}">${esc(w.name)}</option>`).join('')}</select></label></details>`;
}
export function resultsHtml(view,floorId){
 const m=view.metrics?.floors.find(f=>f.id===floorId)||{},rows=view.metrics?.floors||[];
 return `<section class="wt-results"><h3>Useful results</h3><p>Last ${view.metrics?.total.runs||0} retained real runs across this hall. Rehearsals are excluded. Accept a result to count it as useful.</p><div class="wt-grid">${[['Accepted results',m.accepted||0],['Runs needing rework',m.rework||0],['Awaiting your acceptance',m.awaitingAcceptance||0],['Cost per accepted result',money(m.costPerAccepted)],['Average completion time',m.completionMs===null?'—':Math.round((m.completionMs||0)/60000)+' min']].map(([n,v])=>`<article><small>${n}</small><h3>${v}</h3></article>`).join('')}</div><p>Cost includes unsuccessful attempts in the retained history. Time covers agent work through review, not the wait for your acceptance. Reported costs are estimates and may omit subscription usage.</p><table><caption>Compare floor assignments before your next job</caption><thead><tr><th>Floor</th><th>Accepted / runs</th><th>Rework</th><th>Cost / useful result</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.accepted} / ${r.runs}</td><td>${r.rework}</td><td>${money(r.costPerAccepted)}</td></tr>`).join('')}</tbody></table><p>For repeated rework, refine the acceptance checklist or change the specialist on Team. Compare similar jobs; this view does not change your agents automatically.</p><h3>Accepted workflows</h3><p>Open an accepted result and choose “Save accepted workflow”. Reusing it fills the brief, preferences and checklist. Update the facts before running.</p>${(view.workflows||[]).map(w=>`<article><b>${esc(w.name)}</b> <button data-tw="use-workflow" data-workflow="${esc(w.id)}">Use brief</button> <button data-tw="remove-workflow" data-workflow="${esc(w.id)}">Remove</button></article>`).join('')||'<p>No accepted workflows yet.</p>'}</section>`;
}
